/**
 * Embedded official Harel templates + font so Supabase Edge always has them
 * (binary sidecar files are often omitted from Lovable/edge deploys).
 */
export const PROPOSAL_PDF_BASE64 = "";
export const HEALTH_PDF_BASE64 = "";
export const HEEBO_FONT_BASE64 = "";

export function decodeBase64(b64: string): Uint8Array {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}
